#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;

int main() {
    string s;
    cin >> s;
    const int LIM = 1000000;
    vector<char> p(LIM, 1);
    p[0] = p[1] = 0;
    for (int v = 2; (long long)v * v < LIM; v++)
        if (p[v])
            for (int m = v * v; m < LIM; m += v) p[m] = 0;
    int n = s.size();
    vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    for (int i = 0; i < n; i++) {
        if (s[i] == '0' || dp[i] == 0) continue;  // no leading zeros
        int value = 0;
        for (int j = i; j < min(n, i + 6); j++) {
            value = value * 10 + (s[j] - '0');
            if (p[value]) dp[j + 1] = (dp[j + 1] + dp[i]) % MOD;
        }
    }
    printf("%lld\n", dp[n]);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] raw = System.in.readAllBytes();
        int a = 0, b = raw.length;
        while (a < b && raw[a] <= ' ') a++;
        while (b > a && raw[b - 1] <= ' ') b--;
        int n = b - a;
        final int LIM = 1000000;
        final long MOD = 1000000007L;
        boolean[] comp = new boolean[LIM];
        comp[0] = comp[1] = true;
        for (int v = 2; (long) v * v < LIM; v++)
            if (!comp[v])
                for (int m = v * v; m < LIM; m += v) comp[m] = true;
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 0; i < n; i++) {
            if (raw[a + i] == '0' || dp[i] == 0) continue; // no leading zeros
            int value = 0;
            for (int j = i; j < Math.min(n, i + 6); j++) {
                value = value * 10 + (raw[a + j] - '0');
                if (!comp[value]) dp[j + 1] = (dp[j + 1] + dp[i]) % MOD;
            }
        }
        System.out.println(dp[n]);
    }
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
)

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	s := bytes.TrimSpace(raw)
	const LIM = 1000000
	const MOD = 1000000007
	comp := make([]bool, LIM)
	comp[0], comp[1] = true, true
	for v := 2; v*v < LIM; v++ {
		if !comp[v] {
			for m := v * v; m < LIM; m += v {
				comp[m] = true
			}
		}
	}
	n := len(s)
	dp := make([]int64, n+1)
	dp[0] = 1
	for i := 0; i < n; i++ {
		if s[i] == '0' || dp[i] == 0 { // no leading zeros
			continue
		}
		value := 0
		for j := i; j < min(n, i+6); j++ {
			value = value*10 + int(s[j]-'0')
			if !comp[value] {
				dp[j+1] = (dp[j+1] + dp[i]) % MOD
			}
		}
	}
	fmt.Println(dp[n])
}
